   <div class="form-actions form-history"><button type="button" id="form-add-point">\u6B21\u306E\u70B9\u3068\u306E\u9593\u306B\u8FFD\u52A0</button><button type="button" id="form-delete-point">\u8FFD\u52A0\u70B9\u3092\u524A\u9664</button></div>
